// Prepare the query parameters for the Glasp API
const sd = $getWorkflowStaticData('global');
const now = new Date();
const firstRun = !sd.lastRunAt;

let baseDate = firstRun
  ? new Date(now.getTime() - 24 * 60 * 60 * 1000)
  : new Date(sd.lastRunAt);

// 5-minute buffer
baseDate = new Date(baseDate.getTime() - 5 * 60 * 1000);

sd.exportedDocs = sd.exportedDocs || {};

return [
  {
    json: {
      updatedAfter: baseDate.toISOString(),
      exportedDocs: sd.exportedDocs,
    },
  },
];

// Filter out already-exported docs, then format for export
const sd = $getWorkflowStaticData('global');
sd.exportedDocs = sd.exportedDocs || {};
const now = new Date();

// Collect all results from all paginated responses
const allItems = records;
let allResults = [];

for (const item of allItems) {
  const data = item.json;
  // Handle both: direct results array or nested in response
  if (data.results && Array.isArray(data.results)) {
    allResults = allResults.concat(data.results);
  }
}

// Filter: only new docs with highlights
const newDocs = allResults.filter(function(doc) {
  return !sd.exportedDocs[doc.id] && doc.highlights && doc.highlights.length > 0;
});

// Mark as exported
for (const doc of newDocs) {
  sd.exportedDocs[doc.id] = now.toISOString();
}

// Update last run
sd.lastRunAt = now.toISOString();

// Cleanup old tracking (30 days)
const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
for (const [docId, exportedAt] of Object.entries(sd.exportedDocs)) {
  if (new Date(exportedAt) < thirtyDaysAgo) {
    delete sd.exportedDocs[docId];
  }
}

if (newDocs.length === 0) {
  return [{ json: { message: 'No new highlights found.', count: 0 } }];
}

// Format each doc for export
return newDocs.map(function(doc) {
  var lines = [];
  lines.push('## ' + (doc.title || 'Untitled'));
  lines.push('');
  lines.push('**URL:** ' + doc.url);
  lines.push('**Glasp:** ' + doc.glasp_url);
  if (doc.tags && doc.tags.length > 0) {
    lines.push('**Tags:** ' + doc.tags.join(', '));
  }
  if (doc.document_note) {
    lines.push('**Note:** ' + doc.document_note);
  }
  lines.push('');
  lines.push('### Highlights');
  lines.push('');

  for (var i = 0; i < doc.highlights.length; i++) {
    var h = doc.highlights[i];
    lines.push('> ' + h.text);
    if (h.note) {
      lines.push('');
      lines.push('**Note:** ' + h.note);
    }
    var d = new Date(h.highlighted_at).toLocaleDateString();
    lines.push('');
    lines.push('- *' + h.color + ' highlight, ' + d + '*');
    lines.push('');
  }

  var highlightsMarkdown = lines.join('\n');

  var highlightsText = doc.highlights
    .map(function(h) {
      return h.text + (h.note ? ' [Note: ' + h.note + ']' : '');
    })
    .join('\n\n');

  return {
    json: {
      documentId: doc.id,
      title: doc.title || 'Untitled',
      url: doc.url,
      glasp_url: doc.glasp_url,
      domain: doc.domain,
      category: doc.category,
      tags: doc.tags || [],
      author: doc.author || '',
      thumbnail_url: doc.thumbnail_url || '',
      document_note: doc.document_note || '',
      is_favorite: doc.is_favorite || false,
      highlightCount: doc.highlights.length,
      highlightsText: highlightsText,
      highlightsMarkdown: highlightsMarkdown,
      highlights: doc.highlights.map(function(h) {
        return {
          id: h.id,
          text: h.text,
          note: h.note || '',
          color: h.color,
          highlighted_at: h.highlighted_at,
        };
      }),
      createdAt: doc.created_at,
      updatedAt: doc.updated_at,
    },
  };
});
